import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/25-Battle_Service_Design.html","title":"Battle Service 技术设计","lang":"en-US","frontmatter":{},"filePathRelative":"25-Battle_Service_Design.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`25-Battle_Service_Design.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="battle-service-技术设计" tabindex="-1"><a class="header-anchor" href="#battle-service-技术设计"><span>Battle Service 技术设计</span></a></h1><blockquote><p>目的：将战斗系统从 ZoneServer 中适度解耦，构建可扩展、高性能的战斗服务，支撑 PvP/PvE、大型团战、副本等场景，配合 AOI/Scene Orchestrator 提升整体可扩容性。</p></blockquote><h2 id="_1-设计目标" tabindex="-1"><a class="header-anchor" href="#_1-设计目标"><span>1. 设计目标</span></a></h2><ol><li><strong>组件化战斗管线</strong>：技能、Buff、状态、结算模块可独立扩展。</li><li><strong>可卸载</strong>：对于大型战斗，可在 Battle Service 上运行，减轻 ZoneServer 负担。</li><li><strong>低延迟</strong>：战斗计算需在 50 ms 帧内完成，支持回放/校验。</li><li><strong>一致性与容错</strong>：服务异常时可自动接管或回滚，战斗状态可持久化。</li><li><strong>统一数据模型</strong>：与属性/IDL（<code>docs/22</code>）同步，便于客户端/BI 使用。</li></ol><h2 id="_2-架构概览" tabindex="-1"><a class="header-anchor" href="#_2-架构概览"><span>2. 架构概览</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">               ┌───────────────────────┐</span>
<span class="line">               │ Scene Orchestrator    │</span>
<span class="line">               └──────────┬────────────┘</span>
<span class="line">                          │ battle_spawn(scene_id, type)</span>
<span class="line">                          ▼</span>
<span class="line">┌───────────────────────────────────────────────────────────┐</span>
<span class="line">│ Battle Service Cluster                                    │</span>
<span class="line">│  • Matchmaker / Scheduler                                 │</span>
<span class="line">│  • Battle Instance Manager                                │</span>
<span class="line">│  • ECS + Battle Pipeline                                  │</span>
<span class="line">│  • Result Dispatcher / Persistence                        │</span>
<span class="line">└───────┬──────────────────────────────────────────────────┘</span>
<span class="line">        │ events/results</span>
<span class="line">        ▼</span>
<span class="line">┌──────────────────┐        ┌─────────────────────┐</span>
<span class="line">│ ZoneServer       │&lt;------&gt;│ AOI Service         │</span>
<span class="line">└──────────────────┘   AOI/Scene sync       └─────┘</span>
<span class="line">        │ Battle data (Transport)</span>
<span class="line">        ▼</span>
<span class="line">┌──────────────────┐</span>
<span class="line">│ DataProxy / TLog │</span>
<span class="line">└──────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-功能模块" tabindex="-1"><a class="header-anchor" href="#_3-功能模块"><span>3. 功能模块</span></a></h2><h3 id="_3-1-matchmaker-scheduler" tabindex="-1"><a class="header-anchor" href="#_3-1-matchmaker-scheduler"><span>3.1 Matchmaker / Scheduler</span></a></h3><ul><li>接受 ZoneServer 或 Match 服务发送的战斗请求（玩家列表、场景、模式、配置）。</li><li>为请求分配 Battle Instance（可能在同机或其他节点）。</li><li>管理资源（CPU、内存），避免某节点过载；支持迁移/扩缩。</li></ul><h3 id="_3-2-battle-instance-manager" tabindex="-1"><a class="header-anchor" href="#_3-2-battle-instance-manager"><span>3.2 Battle Instance Manager</span></a></h3><ul><li>创建/销毁 Battle 实例，管理生命周期。</li><li>管理战斗场景的状态（地图配置、天气、时间、BUFF 场）。</li><li>维护 Battle 实例对 AOI/Zone 的引用（玩家 ID、实体映射）。</li></ul><h3 id="_3-3-ecs-pipeline" tabindex="-1"><a class="header-anchor" href="#_3-3-ecs-pipeline"><span>3.3 ECS + Pipeline</span></a></h3><ul><li>每个战斗实例使用 ECS（Entity, Component, System）。</li><li>组件示例：TransformComponent、AttributeComponent、SkillComponent、BuffComponent、StateComponent。</li><li>Pipeline 阶段： <ol><li><strong>Input Collection</strong>：收集来自客户端或 AI 的指令（CastSkill、Move、UseItem）。</li><li><strong>Validation</strong>：检查状态（CD、资源、位置）。</li><li><strong>Execution</strong>：更新 Buff/技能/AI，触发事件。</li><li><strong>Settlement</strong>：计算伤害/治疗，更新属性。</li><li><strong>Broadcast</strong>：生成战斗事件，发回 Zone/AOI/Gate。</li></ol></li><li>支持脚本扩展（Lua/ECS 事件），可在 Pipeline 中注入自定义逻辑。</li></ul><h3 id="_3-4-result-dispatcher-persistence" tabindex="-1"><a class="header-anchor" href="#_3-4-result-dispatcher-persistence"><span>3.4 Result Dispatcher / Persistence</span></a></h3><ul><li>将战斗结果（胜利方、积分、掉落、奖励）发送给 Zone/DataProxy/TLog。</li><li>对关键战斗（如 PVP 排位）进行持久化和回放数据记录。</li></ul><h2 id="_4-数据模型" tabindex="-1"><a class="header-anchor" href="#_4-数据模型"><span>4. 数据模型</span></a></h2><h3 id="_4-1-通用实体" tabindex="-1"><a class="header-anchor" href="#_4-1-通用实体"><span>4.1 通用实体</span></a></h3><div class="language-protobuf line-numbers-mode" data-highlighter="prismjs" data-ext="protobuf"><pre><code class="language-protobuf"><span class="line"><span class="token keyword">message</span> <span class="token class-name">BattleEntity</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token builtin">uint64</span> entity_id<span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">EntityType</span> type<span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">AttributeSnapshot</span> attributes<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">repeated</span> <span class="token positional-class-name class-name">BuffState</span> buffs<span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">repeated</span> <span class="token positional-class-name class-name">SkillState</span> skills<span class="token punctuation">;</span></span>
<span class="line">  <span class="token positional-class-name class-name">Transform</span> transform<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>该数据与 <code>docs/22</code> 属性 IDL 对应，供 Battle 与 Zone/AOI 共享。</li></ul><h3 id="_4-2-事件消息" tabindex="-1"><a class="header-anchor" href="#_4-2-事件消息"><span>4.2 事件消息</span></a></h3><ul><li><code>BattleCommand</code>: Client/AI 发起指令。</li><li><code>BattleEvent</code>: Server → Client (技能结果、飘字)。</li><li><code>BattleResult</code>: Final outcome（胜负、积分、掉落）。</li><li>使用统一 Proto ID，Gate/Zone/Battle 共用。</li></ul><h2 id="_5-协议与通信" tabindex="-1"><a class="header-anchor" href="#_5-协议与通信"><span>5. 协议与通信</span></a></h2><ul><li><strong>Zone ↔ Battle</strong>：使用 Transport (NNG) 传输 <code>BattleCommand</code>、<code>BattleEvent</code>、<code>BattleResult</code>。</li><li><strong>Gate ↔ Battle</strong>：Gate 不直接参与，仍通过 Zone 转发。</li><li><strong>AOI ↔ Battle</strong>：AOI 提供玩家位置/可见性，Battle 生成事件后交给 Zone/AOI 广播。</li></ul><h2 id="_6-可扩展性" tabindex="-1"><a class="header-anchor" href="#_6-可扩展性"><span>6. 可扩展性</span></a></h2><ul><li>支持多种战斗模式：Arena (1v1)、Team (5v5)、Raid (40+)、Battlefield (100+).</li><li>可通过配置 / 脚本选择是否 offload 到 Battle Service：小规模战斗可留在 Zone。</li><li>支持 Replay/Inspector：战斗过程中可记录关键帧数据以便回放/裁判。</li></ul><h2 id="_7-容灾与容错" tabindex="-1"><a class="header-anchor" href="#_7-容灾与容错"><span>7. 容灾与容错</span></a></h2><ul><li>Battle 实例定期 checkpoint（状态快照），崩溃后可恢复或重启。</li><li>当 Battle 节点故障，Matchmaker 将战斗标记为异常，通知 Zone/Gate，执行回退策略（如重赛、结算补偿）。</li><li>对于大型战斗，Battle 实例采用冗余（双写或热备）增加可靠性。</li></ul><h2 id="_8-性能要求" tabindex="-1"><a class="header-anchor" href="#_8-性能要求"><span>8. 性能要求</span></a></h2><ul><li>Tick 周期：20 ms - 50 ms（可配置），确保战斗流畅。</li><li>一台 Battle 节点可承载： <ul><li>Arena：1000+ 场并发</li><li>大型战场：10-20 场（取决于 CPU）</li></ul></li><li>使用线程池/Job 系统处理战斗实例，避免阻塞。</li></ul><h2 id="_9-监控与运维" tabindex="-1"><a class="header-anchor" href="#_9-监控与运维"><span>9. 监控与运维</span></a></h2><ul><li>指标：战斗实例数、Tick 时间、事件延迟、失败/重启次数。</li><li>管理接口：查看战斗实例状态、强制结束、迁移、Dump。</li><li>调试工具：Battle Inspector，支持实时观察战斗状态。</li></ul><h2 id="_10-实施计划概述" tabindex="-1"><a class="header-anchor" href="#_10-实施计划概述"><span>10. 实施计划概述</span></a></h2><ol><li><strong>阶段 1</strong>：Battle Service 基础框架（实例管理、简单技能/战斗）。</li><li><strong>阶段 2</strong>：与 Zone/AOI 集成、支持多种战斗模式，结果持久化。</li><li><strong>阶段 3</strong>：大型战场优化、回放、容灾。</li><li><strong>阶段 4</strong>：工具链（Inspector）、AI 对战、战斗脚本热更新。</li></ol><hr><p>该设计为战斗系统提供可扩展、可维护的基础，配合现有 AOI/Scene 架构，支持多种玩法和大规模战斗需求。***</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};